func diffFiles(fileA, fileB, fileC string) error {
    const shardCount = 1000

    // 创建临时分片目录
    tmpDir, err := os.MkdirTemp("", "file_diff")
    if err != nil {
        return err
    }
    defer os.RemoveAll(tmpDir)

    // 1. 分片处理文件B并加载到内存
    bShardSets := make([]map[string]bool, shardCount)
    for i := range bShardSets {
        bShardSets[i] = make(map[string]bool)
    }

    fmt.Println("开始处理文件", fileB)
    if err := processFile(fileB, func(line string) error {
        shardIndex := hash(line) % shardCount
        bShardSets[shardIndex][line] = true
        return nil
    }); err != nil {
        return err
    }

    // 2. 处理文件A并输出差异
    outFile, err := os.Create(fileC)
    if err != nil {
        return err
    }
    defer outFile.Close()

    writer := bufio.NewWriter(outFile)
    defer writer.Flush()

    fmt.Println("开始处理文件", fileA)
    return processFile(fileA, func(line string) error {
        shardIndex := hash(line) % shardCount

        // 内存查找，避免磁盘IO
        if !bShardSets[shardIndex][line] {
            if _, err := writer.WriteString(line + "\n"); err != nil {
                return err
            }
        }
        return nil
    })
}

const shardCount = 1000 // 哈希分片数量

func diffFiles1(fileA, fileB, fileC string) error {
	// 创建临时分片目录
	tmpDir, err := os.MkdirTemp("", "file_diff")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir) // 清理临时文件

	// 1. 分片处理文件B
	bShards := make([]*os.File, shardCount)
	for i := range bShards {
		f, err := os.Create(filepath.Join(tmpDir, fmt.Sprintf("b_shard_%d.tmp", i)))
		if err != nil {
			return err
		}
		defer f.Close()
		bShards[i] = f
	}

	fmt.Println("开始处理文件",fileB)
	if err := processFile(fileB, func(line string) error {
		return writeToShard(line, bShards)
	}); err != nil {
		return err
	}

	// 2. 处理文件A并输出差异
	outFile, err := os.Create(fileC)
	if err != nil {
		return err
	}
	defer outFile.Close()
	writer := bufio.NewWriter(outFile)
	defer writer.Flush()
	fmt.Println("开始处理文件",fileA)
	return processFile(fileA, func(line string) error {
		shardIndex := hash(line) % shardCount
		shardFile := filepath.Join(tmpDir, fmt.Sprintf("b_shard_%d.tmp", shardIndex))

		// 检查是否在B的分片中
		if !lineInFile(line, shardFile) {
			if _, err := writer.WriteString(line + "\n"); err != nil {
				return err
			}
		}
		return nil
	})
}


// 处理大文件（流式读取）
func processFile(path string, processor func(string) error) error {
	file, err := os.Open(path)
	if err != nil {
		return err
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	buf := make([]byte, 0, 64*1024)   // 64KB初始缓冲区
	scanner.Buffer(buf, 10*1024*1024) // 支持10MB长行

	for scanner.Scan() {
		if err := processor(scanner.Text()); err != nil {
			return err
		}
	}
	return scanner.Err()
}

// 哈希分片写入
func writeToShard(line string, shards []*os.File) error {
	shardIndex := hash(line) % shardCount
	_, err := shards[shardIndex].WriteString(line + "\n")
	return err
}

// 在分片文件中查找行
func lineInFile(target, filePath string) bool {
	f, err := os.Open(filePath)
	if err != nil {
		return false
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		if scanner.Text() == target {
			return true
		}
	}
	return false
}

// FNV高效哈希函数
func hash(s string) uint32 {
	h := fnv.New32a()
	h.Write([]byte(s))
	return h.Sum32()
}



func DiffLinkQa(fileA, fileB, fileC string) (int, error) {
	diffCount := 0
	start := time.Now()

	// 使用分片map减少内存占用
	const numShards = 256
	hashSets := make([]map[uint64]struct{}, numShards)
	for i := range hashSets {
		hashSets[i] = make(map[uint64]struct{})
	}

	// 分片函数
	getShard := func(hash uint64) int {
		return int(hash) & (numShards - 1)
	}

	// 读取文件B构建分片哈希集合
	bFile, err := os.Open(fileB)
	if err != nil {
		return diffCount, err
	}
	defer bFile.Close()

	bScanner := bufio.NewScanner(bFile)
	bufB := make([]byte, 0, 64*1024)
	bScanner.Buffer(bufB, 10*1024*1024)

	var linkQaExportdata LinkQaExportdata
	lineCountB := 0
	for bScanner.Scan() {
		line := bScanner.Bytes()
		if err := sonic.Unmarshal(line, &linkQaExportdata); err != nil {
			fmt.Printf("B文件解析错误@行%d: %v\n", lineCountB, err)
			continue
		}
		hash := hashLine([]byte(linkQaExportdata.ShortLink))
		shard := getShard(hash)
		hashSets[shard][hash] = struct{}{}
		lineCountB++

		if lineCountB%1000000 == 0 {
			fmt.Printf("已读取B文件 %d 行\n", lineCountB)
		}
	}
	if err := bScanner.Err(); err != nil {
		return diffCount, err
	}

	// 比较文件A并写入文件C
	aFile, err := os.Open(fileA)
	if err != nil {
		return diffCount, err
	}
	defer aFile.Close()

	cFile, err := os.Create(fileC)
	if err != nil {
		return diffCount, err
	}
	defer cFile.Close()

	writer := bufio.NewWriter(cFile)
	defer writer.Flush()

	aScanner := bufio.NewScanner(aFile)
	bufA := make([]byte, 0, 64*1024)
	aScanner.Buffer(bufA, 10*1024*1024)

	lineCountA := 0

	for aScanner.Scan() {
		lineCountA++
		line := aScanner.Text()
		hash := hashLine([]byte(line))
		shard := getShard(hash)

		if _, exists := hashSets[shard][hash]; !exists {
			if _, err := writer.Write([]byte(line)); err != nil {
				return diffCount, err
			}
			if err := writer.WriteByte('\n'); err != nil {
				return diffCount, err
			}
			diffCount++
			if lineCountA%1000000 == 0 {
				fmt.Printf("已处理A文件 %d 行，发现差异行 %d\n", lineCountA, diffCount)
			}
		}
	}

	if err := aScanner.Err(); err != nil {
		return diffCount, err
	}

	fmt.Printf("处理完成！文件A共 %d 行，文件B共 %d 行，共写入 %d 行差异数据，耗时: %v\n", 
		lineCountA, lineCountB, diffCount, time.Since(start))
	return diffCount, nil
}

